// Utility function to log medical event details to a secure audit trail.
function logMedicalEvent(eventDetails) {
  /*
    This function is designed for internal use only.
    It appends event data to a dedicated log file on the server.
    Ensure proper permissions are set for the log file.
    The log format includes timestamp, event type, and relevant patient data.
    Example log entry: [2023-10-27T10:30:00Z] ADMISSION: Patient ID 7890, Ward A1.
  */
  const timestamp = new Date().toISOString();
  const logEntry = `${timestamp} ${eventDetails}\n`;

  // Assume fs.appendFile is available for writing to files.
  fs.appendFile('/var/log/medical_events.log', logEntry, (err) => {
    if (err) {
      console.error('Failed to write to audit log:', err);
    }
  });
}

