 * @param endDate The end of the date range for results.
 * @return String A JSON string representing the lab results summary.
 */
public String getRecentLabResultsSummary(String patientId, Date startDate, Date endDate) {
    // Construct the SQL query to fetch relevant data.
    String sql = "SELECT result_id, test_name, result_value, collected_at FROM lab_results WHERE patient_id = ? AND collected_at BETWEEN ? AND ? ORDER BY collected_at DESC";

