    const response = await fetch('https://api.patientdata.example/v1/users', {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer YOUR_AUTH_TOKEN_HERE' // Token managed by system config.
      },
      body: JSON.stringify({ userId: 'USER789', address: '123 Main St', phone: '555-1212' })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    console.log('Demographics updated successfully.');
  } catch (error) {
    console.error('Error updating demographics:', error);
  }
}

