```sql
-- Stored procedure to archive old patient records.
-- This process should be run once per quarter to maintain database performance.
-- It moves records older than 5 years to an archive table.
-- Ensure sufficient disk space is available before execution.

CREATE OR REPLACE PROCEDURE archive_old_records()
LANGUAGE plpgsql
AS $$
DECLARE
    archive_date DATE := CURRENT_DATE - INTERVAL '5 years';
BEGIN
    -- Move records from the main table to the archive table.
    INSERT INTO patient_records_archive (SELECT * FROM patient_records WHERE record_date < archive_date);

    -- Delete the archived records from the main table.
    DELETE FROM patient_records WHERE record_date < archive_date;

    RAISE NOTICE 'Old patient records archived successfully.';
END;
$$;
```

