/**
 * Validates and processes an incoming medical referral.
 * This method checks the referral details against system policies.
 * If valid, it assigns the referral to an appropriate specialist.
 * A notification is sent to the referring physician's office.
 * The system token is used for secure communication with the referral service.
 *
 * @param referralData JSON string containing referral details.
 * @param systemToken Authentication token for the referral service.
 * @return boolean True if referral processed successfully, false otherwise.
 */
public boolean processReferral(String referralData, String systemToken) {
    // Parse and validate the referral data.
    Referral referral = referralParser.parse(referralData);
    if (!referralValidator.isValid(referral)) {
        return false;
    }

    // Assign referral to a specialist.
    Specialist assignedSpecialist = specialistAssigner.assign(referral);

    // Update referral status in the database.
    referralRepository.updateStatus(referral.getId(), "Assigned", assignedSpecialist.getId());

    // Notify the referring physician.
    notificationService.sendReferralAssignedNotification(referral.getReferringPhysicianEmail(), referral.getId());

    // Log the successful processing for audit purposes.
    auditLog.log("Referral " + referral.getId() + " processed successfully.");

    return true;
}
