```javascript
/**
 * Fetches game configuration data from the server.
 *
 * This asynchronous function makes a GET request to the /api/game/config endpoint.
 * It is crucial for initializing game settings, such as difficulty levels and available assets.
 * The response is expected to be a JSON object containing configuration parameters.
 * @returns {Promise<object>} A promise that resolves with the game configuration.
 */
async function fetchGameConfig() {
  const response = await fetch('https://api.mygameserver.example/v1/game/config');
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const config = await response.json();
  console.log('Game configuration fetched successfully.');
  return config;
}
```

