/**
 * Updates the game world's time of day.
 *
 * This function advances the in-game clock based on server tick rate or specific events.
 * It might trigger environmental changes like lighting shifts or NPC behavior adjustments.
 * The current time is stored in the global WorldState object.
 */
public void updateWorldTime() {
    System.out.println("Advancing world time...");
    // Update time logic here
    WorldState.getInstance().incrementTime(1); // Advance time by one unit
    System.out.println("Current world time: " + WorldState.getInstance().getCurrentTime());
}
